{"parentUuid":"f868bf67-bc22-4fac-8f60-0741780923ff","isSidechain":false,"promptId":"2e5cb967-b9a2-45a2-bfed-2747e7796993","type":"user","message":{"role":"user","content":[{"tool_use_id":"toolu_01CbicPnjw9ouvEfTXuAB8HZ","type":"tool_result","content":"1\\t/** @catalog 접기/펼치기 섹션 그룹 */\\n2\\timport React from 'react'\\n3\\timport { ExpandIndicator } from './indicators'\\n4\\t\\n5\\timport type { NodeState } from '../pattern/types'\\n6\\timport type { AriaComponentProps } from './types'\\n7\\timport { getNodeLabel } from './types'\\n8\\timport { Aria } from '../primitives/aria'\\n9\\timport { accordion } from '../pattern/roles/accordion'\\n10\\timport { ax } from '@styles/ax'\\n11\\timport './Accordion.css'\\n12\\t\\n13\\ttype AccordionProps = AriaComponentProps\\n14\\t\\n15\\tconst defaultRenderItem = (props: React.HTMLAttributes<HTMLElement>, item: Record<string, unknown>, state: NodeState): React.ReactElement => {\\n16\\t  const label = getNodeLabel(item)\\n17\\t  const isGroup = state.level === 1\\n18\\t\\n19\\t  if (isGroup) {\\n20\\t    return (\\n21\\t      <div>\\n22\\t        <div {...props} className={ax({ role: 'item', interactive: 'item', content: 'text', layout: 'spread', weight: 'semi', width: 'full' })}>\\n23\\t          <span className={ax({ text: state.focused ? 'primary' : 'secondary' })}>{label}</span>\\n24\\t          <span className={\`accordion-chevron \${ax({ flex: 'none', text: 'muted' })}\`} data-expanded={state.expanded || undefined}>\\n25\\t            <ExpandIndicator />\\n26\\t          </span>\\n27\\t        </div>\\n28\\t        {state.slotProps && (\\n29\\t          <div {...state.slotProps} className={ax({ layout: 'stack' })}>\\n30\\t            <span>{label} content</span>\\n31\\t          </div>\\n32\\t        )}\\n33\\t      </div>\\n34\\t    )\\n35\\t  }\\n36\\t\\n37\\t  return (\\n38\\t    <div {...props} className={ax({ textStyle: 'body', text: 'secondary', padding: 'md' })}>\\n39\\t      <span>{label}</span>\\n40\\t    </div>\\n41\\t  )\\n42\\t}\\n43\\t\\n44\\texport function Accordion({\\n45\\t  data,\\n46\\t  plugins = [],\\n47\\t  onChange,\\n48\\t  renderItem = defaultRenderItem,\\n49\\t  className,\\n50\\t  'aria-label': ariaLabel,\\n51\\t}: AccordionProps) {\\n52\\t  return (\\n53\\t    <div className={className ?? ax({ layout: 'stack' })}>\\n54\\t      <Aria pattern={accordion} data={data} plugins={plugins} onChange={onChange} aria-label={ariaLabel}>\\n55\\t        <Aria.Item render={renderItem} />\\n56\\t      </Aria>\\n57\\t    </div>\\n58\\t  )\\n59\\t}\\n60\\t"}]},"uuid":"cebeea04-746c-47a2-802e-ae036635adf0","timestamp":"2026-04-16T10:35:36.135Z","toolUseResult":{"type":"text","file":{"filePath":"/Users/user/Desktop/aria/src/interactive-os/ui/Accordion.tsx","content":"/** @catalog 접기/펼치기 섹션 그룹 */\\nimport React from 'react'\\nimport { ExpandIndicator } from './indicators'\\n\\nimport type { NodeState } from '../pattern/types'\\nimport type { AriaComponentProps } from './types'\\nimport { getNodeLabel } from './types'\\nimport { Aria } from '../primitives/aria'\\nimport { accordion } from '../pattern/roles/accordion'\\nimport { ax } from '@styles/ax'\\nimport './Accordion.css'\\n\\ntype AccordionProps = AriaComponentProps\\n\\nconst defaultRenderItem = (props: React.HTMLAttributes<HTMLElement>, item: Record<string, unknown>, state: NodeState): React.ReactElement => {\\n  const label = getNodeLabel(item)\\n  const isGroup = state.level === 1\\n\\n  if (isGroup) {\\n    return (\\n      <div>\\n        <div {...props} className={ax({ role: 'item', interactive: 'item', content: 'text', layout: 'spread', weight: 'semi', width: 'full' })}>\\n          <span className={ax({ text: state.focused ? 'primary' : 'secondary' })}>{label}</span>\\n          <span className={\`accordion-chevron \${ax({ flex: 'none', text: 'muted' })}\`} data-expanded={state.expanded || undefined}>\\n            <ExpandIndicator />\\n          </span>\\n        </div>\\n        {state.slotProps && (\\n          <div {...state.slotProps} className={ax({ layout: 'stack' })}>\\n            <span>{label} content</span>\\n          </div>\\n        )}\\n      </div>\\n    )\\n  }\\n\\n  return (\\n    <div {...props} className={ax({ textStyle: 'body', text: 'secondary', padding: 'md' })}>\\n      <span>{label}</span>\\n    </div>\\n  )\\n}\\n\\nexport function Accordion({\\n  data,\\n  plugins = [],\\n  onChange,\\n  renderItem = defaultRenderItem,\\n  className,\\n  'aria-label': ariaLabel,\\n}: AccordionProps) {\\n  return (\\n    <div className={className ?? ax({ layout: 'stack' })}>\\n      <Aria pattern={accordion} data={data} plugins={plugins} onChange={onChange} aria-label={ariaLabel}>\\n        <Aria.Item render={renderItem} />\\n      </Aria>\\n    </div>\\n  )\\n}\\n","numLines":60,"startLine":1,"totalLines":60}},"sourceToolAssistantUUID":"f868bf67-bc22-4fac-8f60-0741780923ff","userType":"external","entrypoint":"cli","cwd":"/Users/user/Desktop/aria","sessionId":"82c8ba0c-7a41-45e9-9607-4dd06b6060ac","version":"2.1.110","gitBranch":"main","slug":"parallel-giggling-pillow"}
